parameters.text:
=Here is the raw government policy document text extracted from the citizen's uploaded file. Read it fully and return the structured JSON as instructed.

Policy Text:
{{ $json.content.parts[0].text }}

parameters.jsCode:
// Get raw output
let raw = items[0].json.output || "";

// Remove markdown fences
raw = raw
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .replace(/^\s+|\s+$/g, '');

// If response wraps JSON as a string literal with escaped quotes, fix it
// Example: "{\"policy_name\": \"Cash...\"}"
if (/^"{/.test(raw) && /}"$/.test(raw)) {
  try {
    raw = JSON.parse(raw);
    raw = JSON.stringify(raw);
  } catch (e) {
    // Continue to next fallback
  }
}

// Try direct JSON parsing
try {
  const parsed = JSON.parse(raw);
  return [{ json: parsed }];
} catch (err) {
  // Try to auto-extract JSON substring
  const match = raw.match(/\{[\s\S]*\}/);
  if (match) {
    try {
      const parsed = JSON.parse(match[0]);
      return [{ json: parsed }];
    } catch (err2) {
      throw new Error("JSON parse failed. Extracted block also invalid.\n" + match[0]);
    }
  }

  // Final fallback
  throw new Error("JSON parsing failed.\nRaw received:\n" + raw);
}

const items = $input.first().json.data;

// Extract all text values
const allTexts = items.map(item => 
  item.content?.parts?.[0]?.text || ""
).filter(Boolean);

// Deduplicate by taking only unique texts
const uniqueTexts = [...new Set(allTexts)];

// Join into single clean document
const cleanText = uniqueTexts.join("\n\n");

return [{
  json: {
    text: cleanText
  }
}];

